export function lookupDTC(code: string): DTCEntry | undefined {
  return dtcDatabase[code.toUpperCase()];
}

export function searchDTCs(query: string): DTCEntry[] {
  const q = query.toLowerCase();
  return Object.values(dtcDatabase).filter(
    (dtc) =>
      dtc.code.toLowerCase().includes(q) ||
      dtc.description.includes(query) ||
      dtc.system.includes(query) ||
      dtc.causes.some((c) => c.includes(query))
  );
}

export function getDTCsByCategory(category: "P" | "B" | "C" | "U"): DTCEntry[] {
  return Object.values(dtcDatabase).filter((dtc) => dtc.category === category);
}

export function getDTCsBySeverity(severity: "low" | "medium" | "high"): DTCEntry[] {
  return Object.values(dtcDatabase).filter((dtc) => dtc.severity === severity);
}

export function getOBDPidByName(name: string): OBDPid | undefined {
  return obdPids.find((p) => p.name === name);
}

export function getOBDPidsByCategory(category: string): OBDPid[] {
  const categories: Record<string, string[]> = {
    engine: ["ENGINE_RPM", "SPEED", "ENGINE_LOAD", "THROTTLE_POSITION", "ENGINE_RUNTIME", "ENGINE_ABSOLUTE_LOAD", "RELATIVE_THROTTLE_POSITION"],
    temperature: ["ENGINE_COOLANT_TEMPERATURE", "AIR_INTAKE_TEMPERATURE", "AMBIENT_AIR_TEMPERATURE", "ENGINE_OIL_TEMPERATURE"],
    fuel: ["FUEL_PRESSURE", "MAF", "FUEL_LEVEL", "FUEL_TYPE", "ETHANOL_LEVEL", "FUEL_CONSUMPTION_RATE", "FUEL_RAIL_PRESSURE", "FUEL_RAIL_GAUGE_PRESSURE"],
    pressure: ["INTAKE_MANIFOLD_PRESSURE", "BAROMETRIC_PRESSURE"],
    oxygen: ["OXYGEN_SENSOR_1", "OXYGEN_SENSOR_2", "OXYGEN_SENSOR_3", "OXYGEN_SENSOR_4", "OXYGEN_SENSOR_5", "OXYGEN_SENSOR_6", "OXYGEN_SENSOR_7", "OXYGEN_SENSOR_8"],
    electrical: ["CONTROL_MODULE_VOLTAGE", "COMMANDED_EQUIVALENCE_RATIO"],
    egr: ["COMMANDED_EGR", "EGR_ERROR"],
    fuelTrim: ["SHORT_TERM_BANK_1", "SHORT_TERM_BANK_2", "LONG_TERM_BANK_1", "LONG_TERM_BANK_2"],
    distance: ["DISTANCE_TRAVELED_MIL_ON", "DISTANCE_TRAVELED_AFTER_CODES_CLEARED", "TIME_TRAVELED_MIL_ON", "TIME_SINCE_CODES_CLEARED"],
  };
  const names = categories[category] || [];
  return obdPids.filter((p) => names.includes(p.name));
}

/**
 * Parse DTC code category from first character
 * Based on kotlin-obd-api TroubleCodes.kt logic
 */
export function parseDTCCategory(code: string): { letter: string; description: string } {
  const firstChar = code.charAt(0).toUpperCase();
  switch (firstChar) {
    case "P": return { letter: "P", description: "Powertrain - محرك وناقل حركة" };
    case "C": return { letter: "C", description: "Chassis - شاسيه" };
    case "B": return { letter: "B", description: "Body - هيكل" };
    case "U": return { letter: "U", description: "Network - شبكة اتصال" };
    default: return { letter: "?", description: "غير معروف" };
  }
}
